import{_ as t,a as s,b as n,c as r,d as a,e as i,f as o}from"./chunks/linebox-math-dialog.C07gskZO.js";import{_ as l,o as u,c as d,a3 as c}from"./chunks/framework.BlfGB29P.js";const L=JSON.parse('{"title":"SVG LineBox Math","description":"","frontmatter":{"title":"SVG LineBox Math"},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/svg-linebox-math.md","filePath":"fr/projects/grafik-visual-studio/svg-linebox-math.md","lastUpdated":1793126212000}'),p={name:"fr/projects/grafik-visual-studio/svg-linebox-math.md"};function g(m,e,v,f,h,b){return u(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="svg-linebox-math" tabindex="-1">SVG LineBox Math <a class="header-anchor" href="#svg-linebox-math" aria-label="Permalink to &quot;SVG LineBox Math {#svg-linebox-math}&quot;">​</a></h1><h2 id="praxisbeispiel-zwei-positive-leistungswerte-zusammenfuhren" tabindex="-1">Exemple pratique : Fusionner deux valeurs de puissance positives <a class="header-anchor" href="#praxisbeispiel-zwei-positive-leistungswerte-zusammenfuhren" aria-label="Permalink to &quot;Exemple pratique : Fusionner deux valeurs de puissance positives {#praxisbeispiel-zwei-positive-leistungswerte-zusammenfuhren}&quot;">​</a></h2><p>Un onduleur peut fournir les puissances de charge et de décharge sous forme de <strong>deux valeurs distinctes, toutes deux positives</strong>. Pour obtenir un affichage de puissance unifié, il est nécessaire de générer une valeur unique dont le signe indique le sens du flux. <strong>SVG LineBox Math</strong> calcule cette différence directement dans le navigateur de l&#39;écran d&#39;affichage. Aucun capteur « template » (modèle) ni automatisation supplémentaire dans Home Assistant n&#39;est requis : Home Assistant fournit les valeurs des capteurs, tandis que l&#39;ordinateur de l&#39;écran se charge des calculs. La connexion existante et le transfert de données continuent toutefois de générer une certaine charge.</p><h3 id="editor-werte-erfassen-und-berechnen" tabindex="-1">Éditeur : Acquisition et calcul des valeurs <a class="header-anchor" href="#editor-werte-erfassen-und-berechnen" aria-label="Permalink to &quot;Éditeur : Acquisition et calcul des valeurs {#editor-werte-erfassen-und-berechnen}&quot;">​</a></h3><p><img src="'+t+'" alt="Éditeur avec des widgets numériques colorés, des liaisons de valeurs et une « MathBox » à côté de l&#39;indicateur de batterie"></p><p><em>Les widgets auxiliaires colorés permettent de suivre le traitement des données au sein de l&#39;éditeur. Les couleurs rouge et bleu distinguent les deux valeurs d&#39;entrée positives, tandis que la « MathBox » grise affiche le résultat calculé. Les lettres aux points de connexion ainsi que les poignées sont des éléments d&#39;aide propres à l&#39;éditeur.</em></p><table tabindex="0"><thead><tr><th>Widget</th><th>Rôle dans l&#39;exemple</th></tr></thead><tbody><tr><td>Deux <strong>widgets « Number »</strong> (numériques), rouge et bleu</td><td>Lire une valeur de capteur pour la charge et la décharge, respectivement, et la transmettre via le point de départ du flux de données activé. Les couleurs servent à les distinguer ; elles ne déterminent pas le signe.</td></tr><tr><td><strong>Connexions de valeurs</strong></td><td>Relier les sorties « Number » aux entrées <strong>O</strong> et <strong>M</strong> du bloc mathématique, et transmettre le résultat calculé depuis la sortie <strong>A</strong> vers l&#39;indicateur de puissance. Ces liaisons sont invisibles lors de l&#39;exécution (runtime).</td></tr><tr><td><strong>Bloc mathématique « SVG LineBox Math »</strong> (gris)</td><td>Soustraire les deux valeurs d&#39;entrée positives l&#39;une de l&#39;autre et fournir la puissance résultante, signe inclus, via la sortie <strong>A</strong>.</td></tr><tr><td><strong>Indicateur de batterie industriel</strong></td><td>Afficher la puissance calculée. La température et l&#39;état de charge restent des mesures distinctes ; ils ne font pas partie de ce calcul de différence.</td></tr><tr><td><strong>Lignes SVG</strong></td><td>Visualiser le flux d&#39;énergie entre les panneaux solaires et la batterie. Elles peuvent être animées ; leur sens doit correspondre à l&#39;affectation départ/arrivée et à la convention de signe choisies.</td></tr><tr><td><strong>Affichages numériques sur les lignes solaires</strong></td><td>Indiquer la puissance solaire correspondante ; ces valeurs ne font pas partie des deux entrées utilisées pour le calcul de la différence au niveau de la batterie.</td></tr><tr><td><strong>Panneaux solaires industriels</strong></td><td>Représenter graphiquement les deux sources photovoltaïques (PV).</td></tr></tbody></table><p>Dans l&#39;éditeur, les entrées <strong>O = 1249</strong> et <strong>M = 0</strong> sont connectées ; le bloc mathématique affiche <strong>1249</strong>. Pour cette configuration, la différence est <strong><code>O - M</code></strong>. Configurez <strong>O</strong> et <strong>M</strong> comme entrées, et <strong>A</strong> comme sortie. Activez la facture 1, sélectionnez <strong>Formule personnalisée</strong>, saisissez <code>O - M</code> et, sous <strong>Sorties</strong>, saisissez <code>A</code>. L&#39;option <strong>Transmettre le résultat en interne vers une entrée</strong> doit rester désactivée. Activez le point de sortie sur les deux widgets numériques (« Number ») et effectuez la connexion à partir de ce point précis.</p><p>La signification du signe est déterminée par l&#39;affectation des capteurs. Si <strong>O correspond à la puissance de charge</strong> et <strong>M à la puissance de décharge</strong>, alors :</p><table tabindex="0"><thead><tr><th>Puissance de charge O</th><th>Puissance de décharge M</th><th>Résultat O − M</th><th>Signification</th></tr></thead><tbody><tr><td>1249 W</td><td>0 W</td><td>+1249 W</td><td>Charge</td></tr><tr><td>0 W</td><td>420 W</td><td>−420 W</td><td>Décharge</td></tr><tr><td>0 W</td><td>0 W</td><td>0 W</td><td>Aucun flux net</td></tr></tbody></table><p>Si les capteurs sont raccordés à l&#39;inverse, la signification du signe est inversée. Pour utiliser la convention opposée, employez <code>M - O</code>. Lorsque les valeurs sont simultanément positives, la différence indique le <strong>flux net</strong>, et non les deux puissances individuelles. Une valeur <strong>0</strong> réelle constitue une donnée d&#39;entrée valide ; une valeur de capteur manquante ou invalide n&#39;est pas automatiquement remplacée par zéro.</p><h3 id="runtime-anzeige-ohne-hilfswidgets" tabindex="-1">Exécution (Runtime) : Affichage sans widgets auxiliaires <a class="header-anchor" href="#runtime-anzeige-ohne-hilfswidgets" aria-label="Permalink to &quot;Exécution (Runtime) : Affichage sans widgets auxiliaires {#runtime-anzeige-ohne-hilfswidgets}&quot;">​</a></h3><p><img src="'+s+'" alt="Exécution avec lignes solaires et affichage de la batterie ; les widgets auxiliaires colorés et la MathBox sont masqués"></p><p><em>L&#39;environnement d&#39;exécution (Runtime) affiche la visualisation finale. La puissance de la batterie apparaît en bleu, la température en magenta et l&#39;état de charge en vert. La flèche directionnelle aide à visualiser le flux d&#39;énergie. Les captures d&#39;écran ont été prises à des moments différents ; les valeurs mesurées ne correspondent donc pas nécessairement.</em></p><p>À partir de la version <strong>Studio 0.1.287</strong>, cochez l&#39;option <strong>Masquer en exécution</strong> (Hide in Runtime) pour les deux widgets auxiliaires de type « Number » ainsi que pour la « MathBox » (dans l&#39;onglet <strong>WIDGET</strong> en haut), puis enregistrez le projet. Ces éléments restent visibles et modifiables dans l&#39;éditeur, mais n&#39;apparaissent pas sur l&#39;affichage final. <strong>Le transfert de leurs valeurs et les calculs associés continuent de fonctionner.</strong> Les indicateurs de puissance, les éléments représentant la batterie et les lignes SVG restent, quant à eux, affichés.</p><p>Le calcul s&#39;effectue localement dans le navigateur où l&#39;affichage est ouvert. Grâce à ce transfert de valeurs en local, aucune entité HA (Home Assistant) supplémentaire n&#39;est créée, et le résultat n&#39;est pas automatiquement renvoyé vers Home Assistant. Si l&#39;affichage — ou le navigateur correspondant — est fermé, le calcul s&#39;arrête également.</p><h2 id="alternative-zuordnung-batterie-→-wechselrichter" tabindex="-1">Configuration alternative : Batterie → Onduleur <a class="header-anchor" href="#alternative-zuordnung-batterie-→-wechselrichter" aria-label="Permalink to &quot;Configuration alternative : Batterie → Onduleur {#alternative-zuordnung-batterie-→-wechselrichter}&quot;">​</a></h2><p>Un widget de type <strong>Number</strong> peut transmettre une valeur (issue d&#39;une entité ou d&#39;une prévisualisation) à un module de calcul (« Math »). Activez son <strong>point de sortie</strong> dans la section <strong>Flux de données</strong> (Data Flow) et reliez ce point précis à une entrée active du module de calcul. Pour créer des liaisons invisibles, utilisez des connexions de valeurs ou, à partir de la version <strong>0.1.285</strong>, des lignes SVG avec un <strong>Z-index</strong> défini explicitement à <strong>-100 ou moins</strong>. L&#39;élément devient invisible lors de l&#39;exécution, mais les valeurs restent actives.</p><p>Si la puissance <strong>P</strong> circule <strong>vers la batterie</strong> et que <strong>O</strong> (sortie) provient <strong>de la batterie</strong>, alors pour une ligne reliant la batterie à l&#39;onduleur, les conditions suivantes s&#39;appliquent :</p><table tabindex="0"><thead><tr><th>Paramètre</th><th>Valeur</th></tr></thead><tbody><tr><td>O</td><td>Entrée ; <code>sensor.hyper_2000_eg_1_output_pack_power</code></td></tr><tr><td>P</td><td>Entrée ; <code>sensor.hyper_2000_eg_1_pack_input_power</code></td></tr><tr><td>A</td><td>Sortie</td></tr><tr><td>Calcul 1</td><td>Activer ; Formule personnalisée</td></tr><tr><td>Formule</td><td><code>O - P</code></td></tr><tr><td>Sorties</td><td><code>A</code></td></tr><tr><td>Transfert interne</td><td>Désactivé</td></tr></tbody></table><p>Les deux capteurs peuvent fournir des valeurs positives : O = 0, P = 1252 donne <strong>−1252 W</strong> (charge) ; O = 150, P = 0 donne <strong>+150 W</strong> (décharge). Si des valeurs sont actives simultanément, le résultat correspond au flux net. Une valeur de <strong>0 est valide</strong>. Le message « Entrée O : Valeur manquante… » indique qu&#39;aucune valeur valide n&#39;est reçue via la connexion : activez la sortie, vérifiez le point de départ correspondant et affectez la cible de la ligne à l&#39;entrée O. Les valeurs manquantes ne sont pas traitées comme des zéros.</p><p>À partir de <strong>0.1.141</strong>, l&#39;option <strong>Masquer à l&#39;exécution</strong> (dans la section « Calcul ») masque uniquement l&#39;affichage ; tous les calculs et transferts de valeurs restent actifs. La variante <strong>Calcul de valeur</strong> dans <a href="/fr/projects/grafik-visual-studio/datenfluss">HA Graphique – Flux de données</a> utilise la même logique et est activée par défaut avec cette option. Des convertisseurs de valeur et des connexions de valeur invisibles peuvent être placés en amont.</p><p>À partir de la version <strong>0.1.138</strong>, la boîte de dialogue agrandie intègre <strong>quatre calculs distincts</strong>. Chacun dispose de sa propre activation, de sa propre formule (ou calcul de moyenne), de sa propre liste de sorties et d&#39;un aperçu des résultats. Pour les projets existants, le premier calcul reprend les paramètres et les sorties précédemment définis ; les calculs 2 à 4, ainsi que toutes les entrées internes, sont désactivés par défaut.</p><h2 id="große-icon-und-farben" tabindex="-1">Taille, icône et couleurs <a class="header-anchor" href="#große-icon-und-farben" aria-label="Permalink to &quot;Taille, icône et couleurs {#große-icon-und-farben}&quot;">​</a></h2><p>À partir de la version <strong>0.1.140</strong>, l&#39;onglet <strong>WIDGET</strong> propose les cinq mêmes sections CSS que celles disponibles pour les widgets de base : <strong>CSS Général</strong>, <strong>CSS Police et Texte</strong>, <strong>CSS Arrière-plan</strong>, <strong>CSS Bordures</strong> et <strong>CSS Ombres et Espacement</strong>. Ces options permettent de configurer la position, l&#39;affichage, la transparence, la police, l&#39;alignement du texte, l&#39;image d&#39;arrière-plan, les bordures, le <strong>rayon des coins</strong>, les ombres ainsi que les marges internes et externes. La taille de la police, l&#39;alignement du texte, le rayon des coins et la marge interne s&#39;appliquent également à « LineBox Math ». Les points d&#39;ancrage conservent leurs coordonnées géométriques initiales même en cas d&#39;arrondi des angles ; l&#39;utilisation de rayons plus importants peut toutefois éloigner le bord visible de la bordure par rapport aux sommets. Le style CSS personnalisé reste prioritaire sur les paramètres définis dans les champs correspondants. L&#39;onglet <strong>CSS</strong>, quant à lui, contient le code CSS global du projet.</p><p>À partir de la version <strong>0.1.139</strong>, la largeur et la hauteur peuvent être définies indépendamment, dans une plage allant de <strong>32 à 2000 px</strong>, soit via la boîte de dialogue de calcul, soit à l&#39;aide des poignées de redimensionnement dans l&#39;éditeur. Il est ainsi possible de créer des formes rectangulaires. Les 16 points d&#39;ancrage conservent leur position relative, et les connexions continuent d&#39;aboutir perpendiculairement. Pour les widgets de petite taille, les marqueurs de l&#39;éditeur sont réduits afin d&#39;éviter tout chevauchement. Il est conseillé d&#39;utiliser une vue agrandie dans l&#39;éditeur pour faciliter l&#39;assignation des lettres ; En phase d&#39;exécution (runtime), les marqueurs sont masqués.</p><p>Sous <strong>Affichage</strong>, vous pouvez choisir une icône (optionnelle), définir sa taille (8–512 px) et sa couleur, ainsi que les couleurs de l&#39;arrière-plan, de la bordure et du texte du résultat. Les icônes sont ajustées à l&#39;espace disponible. L&#39;application d&#39;une couleur nécessite une icône compatible ; les images matricielles (raster) multicolores conservent leurs couleurs d&#39;origine. L&#39;option <strong>Afficher le résultat</strong> peut être désactivée sans interrompre le calcul ni la transmission des données. Pour une taille de 32 × 32 px, il est judicieux d&#39;utiliser une icône et de masquer le texte du résultat.</p><p>Le champ <strong>Style CSS supplémentaire</strong> permet d&#39;ajouter des déclarations CSS en ligne (inline), par exemple <code>border-radius: 4px; opacity: 0.8;</code>. Ce style est appliqué après les paramètres de couleur et peut les remplacer. Les URL et les expressions exécutables ne sont pas autorisées.</p><p><img src="'+n+'" alt="Petit élément « LineBox Math » avec une icône de calculatrice"></p><p><em>Exemple simple dans l&#39;éditeur, avec une icône et un texte de résultat masqué.</em></p><p><a href="/images/grafik-visual-studio/math-size-icon.png">Ouvrir l&#39;image en taille réelle</a></p><p><img src="'+r+'" alt="Élément « LineBox Math » avec coins arrondis via CSS"></p><p><em>Un rayon d&#39;angle de 24 px est défini dans les bordures CSS. Les points de connexion visibles dans l&#39;éditeur conservent leur position.</em></p><p><a href="/images/grafik-visual-studio/math-css.png">Ouvrir l&#39;image en taille réelle</a></p><h2 id="darstellung-in-der-runtime" tabindex="-1">Affichage en mode exécution (Runtime) <a class="header-anchor" href="#darstellung-in-der-runtime" aria-label="Permalink to &quot;Affichage en mode exécution (Runtime) {#darstellung-in-der-runtime}&quot;">​</a></h2><p><img src="'+a+'" alt="Carré « LineBox-Math » avec un résultat de 90 et des connexions à angle droit"></p><p><em>Scénario de test en mode exécution : le carré et le résultat restent visibles ; les lignes de connexion entrent et sortent à angle droit. Les lettres identifiant les connexions ainsi que les poignées de sélection de l&#39;éditeur sont masquées. Le résultat est calculé selon la formule définie et la somme des valeurs présentes sur chaque entrée utilisée.</em></p><p><a href="/images/grafik-visual-studio/math-runtime.png">Ouvrir l&#39;image en taille réelle</a></p><h2 id="vier-rechnungen-und-ausgangszuordnung" tabindex="-1">Quatre calculs et affectation de sortie <a class="header-anchor" href="#vier-rechnungen-und-ausgangszuordnung" aria-label="Permalink to &quot;Quatre calculs et affectation de sortie {#vier-rechnungen-und-ausgangszuordnung}&quot;">​</a></h2><p><img src="'+i+'" alt="Boîte de dialogue étendue « SVG LineBox Math » avec des calculs distincts et un transfert interne vers l&#39;entrée C"></p><p>La capture d&#39;écran actuelle montre les calculs séparés ainsi que le transfert interne activé vers l&#39;entrée C. Cela permet au « calcul 2 » de traiter directement le résultat issu du « calcul 1 ».</p><h2 id="berechnung-auf-dem-display-computer" tabindex="-1">Calcul sur l&#39;ordinateur d&#39;affichage <a class="header-anchor" href="#berechnung-auf-dem-display-computer" aria-label="Permalink to &quot;Calcul sur l&#39;ordinateur d&#39;affichage {#berechnung-auf-dem-display-computer}&quot;">​</a></h2><p>Les calculs sont effectués dans le navigateur de l&#39;ordinateur d&#39;affichage concerné. Home Assistant fournit les valeurs des entités ; « SVG LineBox Math » calcule les résultats à partir de ces données et les transmet à d&#39;autres widgets au sein de la visualisation. Même dans le cas de calculs enchaînés impliquant plusieurs entrées et sorties, aucune entité ou automatisation supplémentaire dans Home Assistant n&#39;est requise.</p><p>Ainsi, l&#39;ordinateur associé à l&#39;écran prend en charge les calculs et l&#39;affichage. Chaque écran ouvert calcule sa propre visualisation. Home Assistant demeure responsable de la connexion et de l&#39;échange des valeurs des entités ; cette communication génère toujours une certaine charge. Les résultats des calculs effectués localement ne sont pas automatiquement enregistrés dans Home Assistant via le mécanisme interne de transfert vers les points de connexion.</p><p>Les calculs ne sont disponibles que tant que la visualisation est ouverte et que le navigateur correspondant est en cours d&#39;exécution. Pour les processus devant continuer à fonctionner de manière fiable même lorsque l&#39;écran est éteint, il est nécessaire de recourir à un calcul côté serveur ou à une automatisation dans Home Assistant.</p><h2 id="ausgange-konfigurieren" tabindex="-1">Configuration des sorties <a class="header-anchor" href="#ausgange-konfigurieren" aria-label="Permalink to &quot;Configuration des sorties {#ausgange-konfigurieren}&quot;">​</a></h2><p>Définissez d&#39;abord les rôles des connexions dans la partie supérieure. Ensuite, pour chaque calcul activé, saisissez les lettres souhaitées dans le champ <strong>Sorties (par ex. E,F;H)</strong>. Les virgules, points-virgules et espaces sont acceptés comme séparateurs ; les lettres minuscules sont également reconnues. <code>E,F;H</code> attribue le même résultat aux trois sorties E, F et H. Chacun de ces points doit être configuré comme une <strong>sortie</strong> active. Si une lettre est définie comme entrée, un avertissement s&#39;affiche ; une attribution contradictoire ne peut pas être validée. Une sortie ne peut être associée qu&#39;à un seul calcul. Une sortie sans attribution ne fournit aucune valeur.</p><h2 id="ergebnisse-intern-weiterverarbeiten" tabindex="-1">Traitement interne des résultats <a class="header-anchor" href="#ergebnisse-intern-weiterverarbeiten" aria-label="Permalink to &quot;Traitement interne des résultats {#ergebnisse-intern-weiterverarbeiten}&quot;">​</a></h2><p>Chaque calcul dispose d&#39;une option, désactivée par défaut, intitulée <strong>Transmettre le résultat en interne vers une entrée</strong>. Une fois cette option activée, vous pouvez sélectionner une lettre d&#39;entrée active spécifique sous la rubrique <strong>Entrée interne</strong>. D&#39;autres calculs pourront ensuite utiliser cette lettre dans leurs propres formules. Dans ce cas de figure, la transmission interne se substitue aux valeurs provenant des lignes externes ; si l&#39;option est désactivée, les lignes connectées reprennent leur rôle. Un seul résultat interne est autorisé par entrée. L&#39;ordre des numéros de calcul n&#39;a aucune incidence sur la résolution des dépendances.</p><p>Exemple avec A = 150 et B = 30 :</p><table tabindex="0"><thead><tr><th>Calcul</th><th>Formule</th><th>Sorties</th><th>Transmission interne</th><th>Résultat</th></tr></thead><tbody><tr><td>1</td><td><code>A + B</code></td><td><code>E,F;H</code></td><td>activée → Entrée C</td><td>180</td></tr><tr><td>2</td><td><code>C * 2</code></td><td><code>G</code></td><td>désactivée</td><td>360</td></tr><tr><td>3</td><td><code>A - B</code></td><td><code>I</code></td><td>désactivée</td><td>120</td></tr><tr><td>4</td><td>désactivé</td><td>—</td><td>désactivée</td><td>—</td></tr></tbody></table><p>Un calcul ne peut pas renvoyer son résultat vers une entrée dont il dépend lui-même. Les boucles de rétroaction (directes ou indirectes) ainsi que les doubles affectations sont signalées et rejetées avant toute validation. Dans le cas d&#39;une <strong>moyenne de toutes les entrées occupées</strong>, les entrées internes activement affectées sont également prises en compte ; par conséquent, transmettre le résultat de ce calcul de moyenne vers sa propre zone d&#39;entrée constituerait une boucle de rétroaction.</p><p>Une erreur de calcul, telle qu&#39;une division par zéro, interrompt le calcul concerné ainsi que tous les calculs qui en dépendent. Les calculs indépendants continuent de fonctionner. Les valeurs manquantes ne sont pertinentes que si le calcul utilise l&#39;entrée correspondante ; un calcul de moyenne, par exemple, nécessite des valeurs valides sur toutes les entrées occupées. La fenêtre de dialogue affiche des indications pour chaque calcul. Sur les petits écrans, le contenu devient défilant et les zones de calcul sont disposées les unes en dessous des autres.</p><h2 id="grundlagen-und-beispiel-einer-einzelrechnung" tabindex="-1">Principes de base et exemple d&#39;un calcul individuel <a class="header-anchor" href="#grundlagen-und-beispiel-einer-einzelrechnung" aria-label="Permalink to &quot;Principes de base et exemple d&#39;un calcul individuel {#grundlagen-und-beispiel-einer-einzelrechnung}&quot;">​</a></h2><p>L&#39;image suivante montre la fenêtre de dialogue originale issue de Studio 0.1.137. Le calcul continue de fonctionner en tant que « Calcul 1 » dans la fenêtre de dialogue étendue.</p><p><img src="'+o+'" alt="SVG LineBox Math : Fenêtre de dialogue de calcul avec connexions A–P, valeurs d&#39;entrée et moyenne de 90"></p><p>L’image montre la fenêtre de calcul avec la <strong>moyenne de toutes les entrées connectées</strong>. L’entrée <strong>A</strong> contient déjà la somme de ses deux lignes (100 + 50 = <strong>150</strong>), tandis que l’entrée <strong>B</strong> fournit <strong>30</strong>. Le résultat est donc <strong>90</strong>. <strong>G</strong> est configuré comme sortie et transmet ce résultat. Les lettres vertes A, B et G indiquent des points connectés ; les lettres orange correspondent à des points sans ligne. Une entrée non connectée affichant <code>—</code> n’est pas prise en compte dans la moyenne. Dans ce mode de calcul, le champ de formule est désactivé, mais la formule précédemment saisie est conservée.</p><p>À partir de la version Studio 0.1.137, l&#39;élément <strong>SVG LineBox Math</strong> est disponible sous la rubrique <strong>HA Grafik – Spezial</strong>. Il apparaît sous forme de carré, tant dans l&#39;éditeur qu&#39;en mode exécution (Runtime). Ses 16 points de connexion sont désignés par les lettres A à P, dans le sens des aiguilles d&#39;une montre, en commençant par le coin supérieur gauche : A–E en haut, E–I à droite, I–M en bas et M–A à gauche. Chaque côté comporte trois points supplémentaires situés entre les coins. Dans l&#39;éditeur, les points connectés sont affichés en vert et les points libres en orange, avec des lettres très contrastées ; ces repères disparaissent en mode exécution. Les lignes se raccordent à angle droit. Les points A/E sont alimentés par le haut, les points I/M par le bas, et les points latéraux par le bord du côté correspondant.</p><p>Sélectionnez le widget et ouvrez l&#39;option <strong>Modifier le calcul</strong>. Vous pouvez y définir la largeur et la hauteur (32–2000 px), attribuer les rôles <strong>Désactivé</strong>, <strong>Entrée</strong> ou <strong>Sortie</strong> à chaque lettre, et configurer le calcul. Par défaut, les nouveaux points de connexion sont désactivés ; l&#39;attribution d&#39;un rôle d&#39;entrée ou de sortie dans la fenêtre active le point correspondant. Il est également possible d&#39;activer tous les points simultanément via la section <strong>Points de connexion</strong>.</p><p>La fonction <strong>Formule personnalisée</strong> prend en charge les éléments <code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>, les parenthèses, les nombres avec séparateur décimal ainsi que les lettres A à P. La multiplication et la division sont prioritaires sur l&#39;addition et la soustraction. Exemple : <code>(A + B) / C</code>. Lorsque plusieurs lignes sont connectées à une même entrée, leurs valeurs sont additionnées en tenant compte de leur signe : A avec 100 et 50 donne 150 ; B avec 30 donne, dans le cas de <code>A - B</code>, une valeur de 120. L&#39;option <strong>Moyenne de toutes les entrées occupées</strong> comptabilise chaque borne d&#39;entrée occupée une seule fois (voir <code>(150 + 30) / 2 = 90</code>) ; les points non occupés ne sont pas pris en compte.</p><p>L&#39;aperçu affiche les valeurs d&#39;entrée ainsi que le résultat. Les sorties transmettent le résultat en interne vers des lignes SVG, d&#39;autres « LineBoxes » et des widgets capables de récupérer des valeurs numériques via un point d&#39;ancrage. Aucune entité HA (Home Assistant) supplémentaire n&#39;est requise. L&#39;absence de valeurs connectées, des valeurs invalides, des entrées de formule non occupées, une division par zéro ou des boucles de rétroaction interrompent la sortie. Le widget affiche alors <code>—</code> accompagné d&#39;un message d&#39;erreur ; les formules sont évaluées sans exécution de code JavaScript. Les modifications ne sont prises en compte qu&#39;après avoir cliqué sur <strong>Appliquer</strong> ; la fonction « Annuler » est également disponible.</p>',61)])])}const S=l(p,[["render",g]]);export{L as __pageData,S as default};
